#include <iostream>
using namespace std;

enum class State { IDLE, SELECTING, DISPENSING };

const char* stateName(State s) {
    switch(s) { case State::IDLE: return "IDLE"; case State::SELECTING: return "SELECTING"; case State::DISPENSING: return "DISPENSING"; }
}

class VendingMachine {
    State state = State::IDLE;
public:
    void insertCoin() {
        switch(state) {
            case State::IDLE: state = State::SELECTING; cout << "Coin inserted -> SELECTING\n"; break;
            default: cout << "Cannot insert coin now\n";
        }
    }
    void selectItem() {
        switch(state) {
            case State::SELECTING: state = State::DISPENSING; cout << "Item selected -> DISPENSING\n"; break;
            default: cout << "Select an item first\n";
        }
    }
    void dispense() {
        switch(state) {
            case State::DISPENSING: state = State::IDLE; cout << "Item dispensed -> IDLE\n"; break;
            default: cout << "Nothing to dispense\n";
        }
    }
};

int main() {
    VendingMachine vm;
    vm.insertCoin();
    vm.selectItem();
    vm.dispense();
    return 0;
}
